/// 음절 → 전체 한자 후보 목록 (지연 초기화 캐시)
Map<String, List<HanjaFullEntry>>? _hanjaFullBySyllableCache;
Map<String, List<HanjaFullEntry>> get hanjaFullBySyllable {
  final cached = _hanjaFullBySyllableCache;
  if (cached != null) return cached;
  final map = <String, List<HanjaFullEntry>>{};
  for (final h in hanjaFullDb) {
    map.putIfAbsent(h.syllable, () => []).add(h);
  }
  _hanjaFullBySyllableCache = map;
  return map;
}
